"""Pixel Arena level pathing: bots walk a tile map painted in primary colors."""

import heapq

Cell = tuple[int, int]  # (row, col)

_ENTRY_COST = {".": 1, "D": 3, "S": 1, "G": 1}


def find_path(grid: list[str]) -> list[Cell] | None:
    """Cheapest 4-neighbour path from 'S' to 'G', both inclusive.

    '.' floor costs 1 to enter, 'D' door costs 3, '#' is a wall, 'S'/'G' cost 1.
    Return None when G is unreachable.
    """
    if not grid or not grid[0]:
        return None

    start = goal = None
    for r, row in enumerate(grid):
        for c, ch in enumerate(row):
            if ch == "S":
                start = (r, c)
            elif ch == "G":
                goal = (r, c)
    if start is None or goal is None:
        return None

    rows, cols = len(grid), len(grid[0])
    best = {start: 0}
    prev: dict[Cell, Cell] = {}
    heap = [(0, start)]

    while heap:
        cost, cell = heapq.heappop(heap)
        if cost > best.get(cell, -1):
            continue
        if cell == goal:
            path = [cell]
            while path[-1] != start:
                path.append(prev[path[-1]])
            return path[::-1]
        r, c = cell
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if not (0 <= nr < rows and 0 <= nc < cols):
                continue
            ch = grid[nr][nc]
            if ch == "#":
                continue
            ncost = cost + _ENTRY_COST.get(ch, 1)
            if ncost < best.get((nr, nc), float("inf")):
                best[(nr, nc)] = ncost
                prev[(nr, nc)] = cell
                heapq.heappush(heap, (ncost, (nr, nc)))
    return None

